INSERT INTO `certificate_templates` (`id`, `template_name`, `company_name`, `company_logo`, `template_html`, `template_css`, `variables`, `is_active`, `created_at`, `updated_at`) VALUES
(1, 'Tech Company Certificate', 'Tech Innovators Pvt Ltd', NULL, '<div style=\"width:1122px;height:794px;background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);padding:60px;box-sizing:border-box;font-family:Arial,sans-serif\"><div style=\"background:#fff;width:100%;height:100%;border-radius:20px;padding:50px;box-sizing:border-box;position:relative;box-shadow:0 20px 60px rgba(0,0,0,0.3)\"><div style=\"position:absolute;top:30px;left:30px;right:30px;bottom:30px;border:3px solid #667eea;border-radius:10px\"></div><div style=\"position:relative;z-index:10;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:space-between\"><div><div style=\"font-size:18px;color:#667eea;font-weight:600;letter-spacing:3px;margin-bottom:10px\">CERTIFICATE OF COMPLETION</div><div style=\"width:100px;height:3px;background:linear-gradient(90deg,#667eea,#764ba2);margin:0 auto\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;justify-content:center\"><div style=\"font-size:16px;color:#555;margin-bottom:20px\">This is to certify that</div><div style=\"font-size:48px;font-weight:700;color:#2d3748;margin-bottom:20px;font-family:Georgia,serif\">{{student_name}}</div><div style=\"font-size:16px;color:#555;margin-bottom:30px\">has successfully completed the internship program</div><div style=\"font-size:28px;font-weight:600;color:#667eea;margin-bottom:15px\">{{internship_title}}</div><div style=\"font-size:18px;color:#666;margin-bottom:10px\">at <strong>{{company_name}}</strong></div><div style=\"font-size:14px;color:#888\">Duration: {{duration_months}} months | {{start_date}} to {{end_date}}</div></div><div style=\"display:flex;justify-content:space-between;align-items:flex-end;margin-top:40px\"><div style=\"text-align:left\"><div style=\"border-top:2px solid #667eea;width:200px;margin-bottom:5px\"></div><div style=\"font-size:12px;color:#667eea;font-weight:600\">Authorized Signature</div></div><div style=\"text-align:center\"><div style=\"font-size:11px;color:#888;margin-bottom:5px\">Certificate No: {{certificate_number}}</div><div style=\"font-size:10px;color:#aaa\">Issued on {{issue_date}}</div><div style=\"font-size:9px;color:#ccc;margin-top:3px\">Verify: {{certificate_code}}</div></div><div style=\"text-align:right\"><div style=\"border-top:2px solid #667eea;width:200px;margin-bottom:5px\"></div><div style=\"font-size:12px;color:#667eea;font-weight:600\">Company Seal</div></div></div></div></div></div>', '', 'student_name,company_name,internship_title,start_date,end_date', 1, '2026-01-26 04:06:27', '2026-02-03 14:28:16'),
(2, 'Business Corporation', 'Global Business Corp', '', '<div style=\"width:1122px;height:794px;background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);padding:50px;box-sizing:border-box;font-family:Arial,sans-serif\">\n    <div style=\"background:#fff;width:100%;height:100%;border-radius:20px;padding:40px 50px;box-sizing:border-box;position:relative;box-shadow:0 20px 60px rgba(0,0,0,0.3)\">\n        \n        <!-- Corner Decorations -->\n        <div style=\"position:absolute;top:20px;left:20px;width:80px;height:80px;border-top:5px solid #667eea;border-left:5px solid #667eea\"></div>\n        <div style=\"position:absolute;top:20px;right:20px;width:80px;height:80px;border-top:5px solid #667eea;border-right:5px solid #667eea\"></div>\n        <div style=\"position:absolute;bottom:20px;left:20px;width:80px;height:80px;border-bottom:5px solid #667eea;border-left:5px solid #667eea\"></div>\n        <div style=\"position:absolute;bottom:20px;right:20px;width:80px;height:80px;border-bottom:5px solid #667eea;border-right:5px solid #667eea\"></div>\n        \n        <div style=\"position:relative;z-index:10;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:space-between\">\n            \n            <!-- Top Section with Logos -->\n            <div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:10px\">\n                <!-- Left: Internship Adda Logo -->\n                <div style=\"flex:1;text-align:left\">\n                    <img src=\"https://internshipadda.com/icon.png\" alt=\"Internship Adda\" style=\"height:45px;width:auto\">\n                </div>\n                \n                <!-- Center: BlueCollar Logo -->\n                <div style=\"flex:1;text-align:center\">\n                    <img src=\"https://i.ibb.co/j9C8b7Tb/bl.png\" alt=\"BlueCollar Connected Technologies\" style=\"height:50px;width:auto\">\n                </div>\n                \n                <!-- Right: MSME Badge -->\n                <div style=\"flex:1;text-align:right\">\n                    <div style=\"display:inline-block;background:#fff;border:2px solid #667eea;border-radius:12px;padding:8px 12px;box-shadow:0 2px 8px rgba(102,126,234,0.15)\">\n                        <img src=\"https://etimg.etb2bimg.com/photo/93064603.cms\" alt=\"MSME Registered\" style=\"height:38px;width:auto;display:block;margin-bottom:3px\">\n                        <div style=\"font-size:8px;color:#667eea;font-weight:700;text-transform:uppercase;letter-spacing:0.5px\">MSME Registered</div>\n                    </div>\n                </div>\n            </div>\n            \n            <!-- Header -->\n            <div style=\"margin-bottom:15px\">\n                <div style=\"font-size:44px;font-weight:800;color:#667eea;margin-bottom:8px;letter-spacing:2px\">INTERNSHIP CERTIFICATE</div>\n                <div style=\"font-size:15px;color:#666;font-style:italic\">Excellence in Professional Development</div>\n            </div>\n            \n            <!-- Main Content -->\n            <div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;padding:15px 0\">\n                <div style=\"font-size:19px;color:#555;margin-bottom:18px\">This certifies that</div>\n                <div style=\"font-size:52px;font-weight:700;color:#1a1a1a;margin-bottom:18px;font-family:Georgia,serif;text-transform:uppercase\">{{student_name}}</div>\n                <div style=\"font-size:17px;color:#555;margin-bottom:18px\">has successfully completed the internship in</div>\n                <div style=\"background:linear-gradient(90deg,#667eea,#764ba2);color:#fff;font-size:26px;font-weight:600;padding:14px 40px;display:inline-block;border-radius:50px;margin:0 auto 12px\">{{internship_title}}</div>\n                <div style=\"font-size:15px;color:#333;font-weight:600;margin-top:12px\">{{start_date}} — {{end_date}} ({{duration_months}} months)</div>\n                \n                <!-- Company Branding -->\n                <div style=\"font-size:15px;color:#667eea;font-weight:600;margin-top:18px\">\n                    Internship Adda × BlueCollar Connected Technologies Pvt Ltd\n                </div>\n            </div>\n            \n            <!-- Footer with Signatures and QR -->\n            <div style=\"border-top:2px solid #667eea;padding-top:15px;margin-top:auto\">\n                <div style=\"display:grid;grid-template-columns:1fr 1fr 1fr;gap:20px;align-items:flex-end\">\n                    \n                    <!-- Left: Internship Adda Director Signature with Muhar -->\n                    <div style=\"text-align:center;position:relative\">\n                        <!-- Internship Adda Muhar positioned behind signature -->\n                        <img src=\"https://i.ibb.co/cSWbL5Qk/muh.png\" alt=\"Internship Adda Seal\" style=\"position:absolute;width:85px;height:85px;opacity:0.35;left:50%;top:-15px;transform:translateX(-50%);z-index:0\">\n                        \n                        <img src=\"https://i.ibb.co/8DjXhf2X/image-removebg-preview.png\" alt=\"Signature\" style=\"height:48px;width:auto;margin:0 auto 5px;display:block;position:relative;z-index:1\">\n                        <div style=\"width:170px;height:1.5px;background:#333;margin:0 auto 6px;position:relative;z-index:1\"></div>\n                        <div style=\"font-size:11px;color:#667eea;font-weight:600;line-height:1.4;position:relative;z-index:1\">Internship Adda<br>Founder/Co-Founder</div>\n                    </div>\n                    \n                    <!-- Center: QR Code + Certificate Info -->\n                    <div style=\"text-align:center\">\n                        <img src=\"https://i.ibb.co/DDP3HtYw/qr-code.png\" alt=\"QR Code\" style=\"width:75px;height:75px;margin:0 auto 4px;display:block\">\n                        <div style=\"font-size:9px;color:#999;margin-bottom:6px\">Scan to Verify</div>\n                        <div style=\"font-size:10px;color:#666;font-weight:600\">Cert. No: {{certificate_number}}</div>\n                        <div style=\"font-size:9px;color:#999;margin-top:2px\">{{certificate_code}}</div>\n                        <div style=\"font-size:9px;color:#999;margin-top:4px\">Issue Date: {{issue_date}}</div>\n                    </div>\n                    \n                    <!-- Right: BlueCollar Director Signature with Seal -->\n                    <div style=\"text-align:center;position:relative\">\n                        <!-- BlueCollar Seal positioned behind signature -->\n                        <img src=\"https://i.ibb.co/yFRbfYzs/image.png\" alt=\"BlueCollar Seal\" style=\"position:absolute;width:85px;height:85px;opacity:0.35;left:50%;top:-15px;transform:translateX(-50%);z-index:0\">\n                        \n                        <img src=\"https://i.ibb.co/WN0c95wW/Md-Tauseef-Alam-removebg-preview.png\" alt=\"Signature\" style=\"height:48px;width:auto;margin:0 auto 5px;display:block;position:relative;z-index:1\">\n                        <div style=\"width:170px;height:1.5px;background:#333;margin:0 auto 6px;position:relative;z-index:1\"></div>\n                        <div style=\"font-size:11px;color:#667eea;font-weight:600;line-height:1.4;position:relative;z-index:1\">BlueCollar Connected<br>Technologies Pvt Ltd<br>Director</div>\n                    </div>\n                    \n                </div>\n            </div>\n            \n        </div>\n    </div>\n</div>\n', '', NULL, 1, '2026-01-26 04:06:27', '2026-02-04 16:33:42'),
(3, 'Design Studio', 'Creative Design Studio', NULL, '<div style=\"width:1122px;height:794px;background:linear-gradient(135deg,#8e2de2 0%,#4a00e0 100%);padding:50px;box-sizing:border-box;font-family:Arial,sans-serif\"><div style=\"background:#fff;width:100%;height:100%;border-radius:30px;padding:60px;box-sizing:border-box;position:relative;overflow:hidden;box-shadow:0 25px 70px rgba(0,0,0,0.4)\"><div style=\"position:absolute;top:-100px;right:-100px;width:400px;height:400px;background:radial-gradient(circle,rgba(142,45,226,0.1),transparent);border-radius:50%\"></div><div style=\"position:absolute;bottom:-150px;left:-150px;width:500px;height:500px;background:radial-gradient(circle,rgba(74,0,224,0.1),transparent);border-radius:50%\"></div><div style=\"position:relative;z-index:10;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:space-between\"><div><div style=\"display:inline-block;background:linear-gradient(90deg,#8e2de2,#4a00e0);padding:12px 40px;border-radius:50px;margin-bottom:20px\"><span style=\"color:#fff;font-size:16px;font-weight:700;letter-spacing:3px\">CERTIFICATE</span></div><div style=\"font-size:14px;color:#8e2de2;font-weight:600\">OF INTERNSHIP COMPLETION</div></div><div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;padding:20px\"><div style=\"font-size:16px;color:#666;margin-bottom:20px;font-style:italic\">Presented to</div><div style=\"font-size:56px;font-weight:800;background:linear-gradient(90deg,#8e2de2,#4a00e0);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:25px;font-family:Georgia,serif\">{{student_name}}</div><div style=\"font-size:16px;color:#666;margin-bottom:25px\">for successfully completing the internship program</div><div style=\"font-size:30px;font-weight:700;color:#333;margin-bottom:15px\">{{internship_title}}</div><div style=\"font-size:18px;color:#8e2de2;font-weight:600;margin-bottom:20px\">{{company_name}}</div><div style=\"background:#f8f9fa;padding:12px 30px;border-radius:10px;display:inline-block;margin:0 auto\"><span style=\"font-size:13px;color:#555\">{{start_date}} to {{end_date}}</span><span style=\"margin:0 10px;color:#8e2de2\">•</span><span style=\"font-size:13px;color:#555\">{{duration_months}} months</span></div></div><div><div style=\"display:flex;justify-content:space-between;align-items:center;margin-bottom:15px\"><div style=\"flex:1;text-align:left\"><div style=\"width:200px;height:2px;background:linear-gradient(90deg,#8e2de2,transparent);margin-bottom:8px\"></div><div style=\"font-size:11px;color:#8e2de2;font-weight:600\">Authorized By</div></div><div style=\"flex:1;text-align:center\"><div style=\"font-size:10px;color:#999\">{{certificate_number}}</div><div style=\"font-size:9px;color:#ccc;margin-top:2px\">{{certificate_code}}</div></div><div style=\"flex:1;text-align:right\"><div style=\"width:200px;height:2px;background:linear-gradient(90deg,transparent,#4a00e0);margin-bottom:8px;margin-left:auto\"></div><div style=\"font-size:11px;color:#4a00e0;font-weight:600\">Company Seal</div></div></div></div></div></div></div>', '', 'student_name,company_name,internship_title,start_date,end_date', 1, '2026-01-26 04:06:27', '2026-02-03 14:28:16'),
(4, 'Marketing Agency', 'Digital Marketing Pro', NULL, '<div style=\"width:1122px;height:794px;background:linear-gradient(135deg,#f093fb 0%,#f5576c 100%);padding:55px;box-sizing:border-box;font-family:Arial,sans-serif\"><div style=\"background:#fff;width:100%;height:100%;border-radius:25px;padding:55px;box-sizing:border-box;position:relative;box-shadow:0 20px 60px rgba(0,0,0,0.35)\"><div style=\"position:absolute;top:30px;left:30px;width:60px;height:60px;background:linear-gradient(135deg,#f093fb,#f5576c);transform:rotate(45deg);opacity:0.15\"></div><div style=\"position:absolute;top:30px;right:30px;width:60px;height:60px;background:linear-gradient(135deg,#f093fb,#f5576c);border-radius:50%;opacity:0.15\"></div><div style=\"position:absolute;bottom:30px;left:30px;width:60px;height:60px;background:linear-gradient(135deg,#f093fb,#f5576c);border-radius:50%;opacity:0.15\"></div><div style=\"position:absolute;bottom:30px;right:30px;width:60px;height:60px;background:linear-gradient(135deg,#f093fb,#f5576c);transform:rotate(45deg);opacity:0.15\"></div><div style=\"position:absolute;top:25px;left:25px;right:25px;bottom:25px;border:4px double #f5576c;border-radius:15px\"></div><div style=\"position:relative;z-index:10;text-align:center;height:100%;display:flex;flex-direction:column;justify-content:space-between;padding:25px 10px\"><div><div style=\"font-size:48px;font-weight:900;background:linear-gradient(90deg,#f093fb,#f5576c);-webkit-background-clip:text;-webkit-text-fill-color:transparent;margin-bottom:8px;letter-spacing:1px\">CERTIFICATE</div><div style=\"font-size:16px;color:#f5576c;font-weight:600;letter-spacing:4px\">OF ACHIEVEMENT</div><div style=\"width:120px;height:4px;background:linear-gradient(90deg,#f093fb,#f5576c);margin:15px auto\"></div></div><div style=\"flex:1;display:flex;flex-direction:column;justify-content:center;padding:25px 0\"><div style=\"font-size:17px;color:#666;margin-bottom:22px\">This is proudly presented to</div><div style=\"font-size:50px;font-w