(13, 26, 'text', '<div>function getFirstLessonUrl($db, $internshipId) {</div><div>&nbsp; &nbsp; try {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; error_log(\"🔍 Finding first lesson for internship: $internshipId\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; // Get first module</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $moduleStmt = $db-&gt;prepare(\"</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; SELECT id&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; FROM internship_modules&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; WHERE internship_id = ?&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ORDER BY sort_order ASC, id ASC&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; LIMIT 1</div><div>&nbsp; &nbsp; &nbsp; &nbsp; \");</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $moduleStmt-&gt;execute([$internshipId]);</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $moduleId = $moduleStmt-&gt;fetchColumn();</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; if (!$moduleId) {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; error_log(\"⚠️ No modules found - Redirecting to my-internships\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; // ✅ CHANGED: Redirect to my-internships instead of error</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return \'/app/views/learner/my-internships.php\';</div><div>&nbsp; &nbsp; &nbsp; &nbsp; }</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; error_log(\"✅ First module ID: $moduleId\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; // Get first lesson</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $lessonStmt = $db-&gt;prepare(\"</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; SELECT id&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; FROM internship_lessons&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; WHERE module_id = ?&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ORDER BY sort_order ASC, id ASC&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; LIMIT 1</div><div>&nbsp; &nbsp; &nbsp; &nbsp; \");</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $lessonStmt-&gt;execute([$moduleId]);</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $lessonId = $lessonStmt-&gt;fetchColumn();</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; if (!$lessonId) {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; error_log(\"⚠️ No lessons found - Redirecting to my-internships\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; // ✅ CHANGED: Redirect to my-internships</div><div>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; return \'/app/views/learner/my-internships.php\';</div><div>&nbsp; &nbsp; &nbsp; &nbsp; }</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; error_log(\"✅ First lesson ID: $lessonId\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; $redirectUrl = \"/app/views/learner/internship-player.php?id={$internshipId}&amp;lesson={$lessonId}\";</div><div>&nbsp; &nbsp; &nbsp; &nbsp; error_log(\"🚀 Redirect URL: $redirectUrl\");</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; &nbsp; &nbsp; return $redirectUrl;</div><div>&nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</div><div>&nbsp; &nbsp; } catch (Exception $e) {</div><div>&nbsp; &nbsp; &nbsp; &nbsp; error_log(\"❌ Error: \" . $e-&gt;getMessage());</div><div>&nbsp; &nbsp; &nbsp; &nbsp; return \'/app/views/learner/my-internships.php\';</div><div>&nbsp; &nbsp; }</div><div>}</div><div><br></div>', NULL, 0, '2026-02-15 05:20:38', '2026-02-15 05:20:38'),
